# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_boot() {
    journalctl --list-boots --no-pager 2>/dev/null |
        gawk 'NR > 1 && NF >= 3 { print $1; print $3 }'
}

_choice_facility() {
    cat <<-'EOF' | _argc_util_comp_multi ,
	kern	Kernel messages
	user	Random user-level messages
	mail	Mail system
	daemon	System daemons
	auth	Security/authorization messages
	syslog	Messages generated internally by syslogd
	lpr	Line printer subsystem
	news	Network news subsystem
	uucp	UUCP subsystem
	cron	Clock daemon
	authpriv	Security/authorization messages (private)
	ftp	FTP daemon
	local0	Local use 0
	local1	Local use 1
	local2	Local use 2
	local3	Local use 3
	local4	Local use 4
	local5	Local use 5
	local6	Local use 6
	local7	Local use 7
	EOF
}

_choice_field() {
    journalctl -N --no-pager 2>/dev/null
}

_choice_identifier() {
    journalctl -F SYSLOG_IDENTIFIER --no-pager 2>/dev/null
}

_choice_invocation() {
    local unit=${argc_unit:-${argc_user_unit:-}}
    [[ -n $unit ]] || return 0
    if [[ -n ${argc_unit:-} ]]; then
        journalctl --list-invocations --no-pager -u "$unit" 2>/dev/null | gawk 'NR > 1 { print $1 }'
    else
        journalctl --list-invocations --no-pager --user-unit "$unit" 2>/dev/null | gawk 'NR > 1 { print $1 }'
    fi
}

_choice_machine() {
    command -v machinectl >/dev/null 2>&1 || return 0
    machinectl list --no-legend --no-pager 2>/dev/null | gawk '{ print $1 }'
}

_choice_namespace() {
    journalctl --list-namespaces --no-pager 2>/dev/null
}

_choice_output_fields() {
    _choice_field | _argc_util_comp_multi ,
}

_choice_priority() {
    cat <<-'EOF'
	0	Emergency
	1	Alert
	2	Critical
	3	Error
	4	Warning
	5	Notice
	6	Informational
	7	Debug
	EOF
}

_choice_unit() {
    command -v systemctl >/dev/null 2>&1 || return 0
    _helper_unit_files
}

_choice_user_unit() {
    command -v systemctl >/dev/null 2>&1 || return 0
    _helper_unit_files --user
}

_helper_unit_files() {
    systemctl "$@" list-unit-files --no-legend --no-pager 2>/dev/null | gawk '{ print $1 }'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
